    tecladoTitulo: { tr: "Klavye ve fare", en: "Keyboard and mouse", es: "Teclado y ratón", pt: "Teclado e mouse" },
    tecladoDesc: { tr: "Bir tuşa tıklayın, sonra yeni tuşa basın ya da fareye tıklayın. Sağ tık temizler. Her eylemin iki tuşu olabilir.", en: "Click a key, then press the new key or click a mouse button. Right-click clears it. Each action can have two keys.", es: "Haz clic en una tecla y pulsa la nueva o un botón del ratón. Clic derecho la borra. Cada acción admite dos teclas.", pt: "Clique numa tecla e depois aperte a tecla nova ou clique um botão do mouse. O botão direito limpa. Cada ação pode ter duas teclas." },
